references.example:
auto owner = std::make_unique<int>(18);
int snapshot = *owner;
owner.reset();
// Прежний управляемый int уничтожен; owner пуст.
// snapshot — отдельный int со значением 18, он по-прежнему жив.
// Сохранённый адрес прежнего объекта, в отличие от snapshot, не разрешал бы чтение после reset().

auto exclusive = std::make_unique<int>(24);
auto group = std::make_shared<int>(36);
std::weak_ptr<int> observer = group;
{
  auto another = group;
  group.reset();
  // another ещё владеет 36; observer.lock() может получить владельца.
}
// Сильных владельцев 36 больше нет: observer.lock() вернёт пустой shared_ptr.
// Отдельный int со значением 24 по-прежнему принадлежит exclusive.

auto owner = std::make_unique<int>(18);
const int* view = owner.get();
*owner = 25;
// *view == 25: объект один, get() не создал копию.
// Вручную вызывать delete view нельзя: ресурс принадлежит owner.

auto first = std::make_unique<int>(18);
int* view = first.get();
auto second = std::move(first);
// first == nullptr; second.get() == view; *second == 18.
// view не владеет объектом; его жизнь теперь контролирует second.

auto owner = std::make_unique<int>(18);
owner.reset();
// owner.get() == nullptr; прежний int уже удалён.
owner = std::make_unique<int>(25); // новый независимый объект
